begin;
create function pg_temp.ok(ok boolean,label text) returns void language plpgsql as $$
begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; end $$;
create function pg_temp.denied(command text) returns void language plpgsql as $$
begin begin execute command; exception when insufficient_privilege then return; end; raise exception 'Expected access denial'; end $$;
create function pg_temp.rejected(command text) returns void language plpgsql as $$
begin begin execute command; exception when others then return; end; raise exception 'Expected rejection'; end $$;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data)
select ('b0220000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'announcement-'||n||'@example.invalid',now(),'{"onboarding_v2":true}' from generate_series(1,6) n;
create temp table announcement_fixture(key text primary key,value text); grant all on announcement_fixture to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','b0220000-0000-4000-8000-000000000001',true);
insert into announcement_fixture values('org_a',public.create_company_workspace('Announcement Company A','Owner A')::text);
insert into announcement_fixture values('operator',public.create_membership_invite(public.active_organization_id(),array['operator'])->>'code');
insert into announcement_fixture values('supervisor',public.create_membership_invite(public.active_organization_id(),array['supervisor'])->>'code');
insert into announcement_fixture values('publisher',public.create_membership_invite(public.active_organization_id(),array['supervisor'],array['announcements_manage'])->>'code');
insert into announcement_fixture values('later',public.create_membership_invite(public.active_organization_id(),array['operator'])->>'code');
select set_config('request.jwt.claim.sub','b0220000-0000-4000-8000-000000000002',true);
select public.redeem_membership_invite((select value from announcement_fixture where key='operator'),'Operator A');
select set_config('request.jwt.claim.sub','b0220000-0000-4000-8000-000000000003',true);
select public.redeem_membership_invite((select value from announcement_fixture where key='supervisor'),'Supervisor A');
select set_config('request.jwt.claim.sub','b0220000-0000-4000-8000-000000000005',true);
select public.redeem_membership_invite((select value from announcement_fixture where key='publisher'),'Announcement Manager');
select set_config('request.jwt.claim.sub','b0220000-0000-4000-8000-000000000004',true);
insert into announcement_fixture values('org_b',public.create_company_workspace('Announcement Company B','Owner B')::text);
select set_config('request.jwt.claim.sub','b0220000-0000-4000-8000-000000000002',true);
select pg_temp.denied($q$select public.publish_organization_announcement(public.active_organization_id(),'b0220000-0000-4000-8000-000000000020','{"title":"Forged announcement","body":"Operator cannot publish"}')$q$);
select set_config('request.jwt.claim.sub','b0220000-0000-4000-8000-000000000003',true);
select pg_temp.denied($q$select public.publish_organization_announcement(public.active_organization_id(),'b0220000-0000-4000-8000-000000000020','{"title":"Forged announcement","body":"Supervisor needs explicit permission"}')$q$);
select pg_temp.ok(public.organization_announcement_feed()->>'can_publish'='false','ordinary supervisor sees a read-only channel');
select set_config('request.jwt.claim.sub','b0220000-0000-4000-8000-000000000005',true);
insert into announcement_fixture values('path',(select value from announcement_fixture where key='org_a')||'/b0220000-0000-4000-8000-000000000005/b0220000-0000-4000-8000-000000000021/checklist.jpg');
insert into storage.objects(id,bucket_id,name) select gen_random_uuid(),'organization-announcements',value from announcement_fixture where key='path';
select public.publish_organization_announcement(public.active_organization_id(),'b0220000-0000-4000-8000-000000000021',jsonb_build_object('title','Monday maintenance briefing','body','Review the shutdown schedule before the shift.','attachments',jsonb_build_array(jsonb_build_object('path',(select value from announcement_fixture where key='path'),'name','Shutdown checklist'))));
select public.publish_organization_announcement(public.active_organization_id(),'b0220000-0000-4000-8000-000000000021',jsonb_build_object('title','Monday maintenance briefing','body','Review the shutdown schedule before the shift.','attachments',jsonb_build_array(jsonb_build_object('path',(select value from announcement_fixture where key='path'),'name','Shutdown checklist'))));
select pg_temp.rejected($q$select public.publish_organization_announcement(public.active_organization_id(),'b0220000-0000-4000-8000-000000000021','{"title":"Changed announcement","body":"Different payload"}')$q$);
select pg_temp.ok(public.organization_announcement_feed()->>'unread_count'='0','author own announcement is already read');
select pg_temp.ok(public.organization_announcement_feed()->>'participant_count'='4','active company participants reported');
select set_config('request.jwt.claim.sub','b0220000-0000-4000-8000-000000000002',true);
select pg_temp.ok(public.organization_announcement_feed()->>'unread_count'='1','member unread count begins at one');
select pg_temp.ok(public.organization_announcement('b0220000-0000-4000-8000-000000000021')->>'author_name'='Announcement Manager','immutable author and message available to members');
select pg_temp.ok((select count(*)=1 from storage.objects where bucket_id='organization-announcements' and name=(select value from announcement_fixture where key='path')),'member reads announced photo');
select public.mark_organization_announcement_read('b0220000-0000-4000-8000-000000000021');
select public.mark_organization_announcement_read('b0220000-0000-4000-8000-000000000021');
select pg_temp.ok(public.organization_announcement_feed()->>'unread_count'='0','read receipt replay is idempotent');
select pg_temp.ok((select count(*)=1 and bool_and(read) from public.notifications where type='organization_announcement' and reference_id='b0220000-0000-4000-8000-000000000021'),'notification read state follows the opened announcement');
select set_config('request.jwt.claim.sub','b0220000-0000-4000-8000-000000000004',true);
select pg_temp.ok(jsonb_array_length(public.organization_announcement_feed()->'posts')=0,'other company has separate channel');
select pg_temp.denied($q$select public.organization_announcement('b0220000-0000-4000-8000-000000000021')$q$);
select pg_temp.denied($q$select public.organization_announcement_feed((select value::uuid from announcement_fixture where key='org_a'))$q$);
select pg_temp.denied($q$select public.mark_organization_announcement_read('b0220000-0000-4000-8000-000000000021')$q$);
select pg_temp.ok((select count(*)=0 from storage.objects where bucket_id='organization-announcements' and name=(select value from announcement_fixture where key='path')),'other company cannot read attachment');
select set_config('request.jwt.claim.sub','b0220000-0000-4000-8000-000000000006',true);
select public.redeem_membership_invite((select value from announcement_fixture where key='later'),'New member');
select pg_temp.ok(public.organization_announcement_feed()->>'unread_count'='1','new member can read prior company announcements with own unread state');
select set_config('request.jwt.claim.sub','b0220000-0000-4000-8000-000000000001',true);
select public.update_organization_membership(public.active_organization_id(),'b0220000-0000-4000-8000-000000000002',array['operator'],'{}','revoked');
select public.update_organization_membership(public.active_organization_id(),'b0220000-0000-4000-8000-000000000005',array['supervisor'],'{}','active');
select set_config('request.jwt.claim.sub','b0220000-0000-4000-8000-000000000002',true);
select pg_temp.denied($q$select public.organization_announcement('b0220000-0000-4000-8000-000000000021')$q$);
select pg_temp.ok((select count(*)=0 from public.notifications where type='organization_announcement' and reference_id='b0220000-0000-4000-8000-000000000021'),'revoked member cannot read old notification');
select pg_temp.ok((select count(*)=0 from storage.objects where bucket_id='organization-announcements' and name=(select value from announcement_fixture where key='path')),'revoked member loses attachment access');
select set_config('request.jwt.claim.sub','b0220000-0000-4000-8000-000000000005',true);
select pg_temp.denied($q$select public.publish_organization_announcement(public.active_organization_id(),'b0220000-0000-4000-8000-000000000022','{"title":"Permission revoked","body":"Cannot publish now"}')$q$);
reset role;
select pg_temp.ok((select count(*)=1 from public.organization_announcements where id='b0220000-0000-4000-8000-000000000021'),'retry creates exactly one immutable announcement');
select pg_temp.ok((select count(*)=3 from public.notifications where type='organization_announcement' and reference_id='b0220000-0000-4000-8000-000000000021'),'one notification per other active member at publication');
rollback;
